    const job=(await tx.query('SELECT * FROM recruitment_completion_jobs WHERE application_id=$1 FOR UPDATE',[row.id])).rows[0];if(job?.lease_until&&new Date(job.lease_until).getTime()>Date.now())throw Object.assign(new Error('Cleanup is running. Retry after it finishes.'),{statusCode:409});
